import json,sys,numpy as np
from pathlib import Path
root=Path(sys.argv[1]);summary=json.loads((root/'summary.json').read_text());assert summary['completed']==summary['total']==36
rows=summary['results'];good=[r for r in rows if r['task_success']]
out=dict(successes=len(good),whole_sequence_mean_hover_proxy=float(np.mean([r['whole_sequence']['rotor_burden_hover_ratio'] for r in good])),whole_to_walk_accumulated_proxy_ratio=float(sum(r['whole_sequence']['rotor_proxy'] for r in good)/sum(r['rotor_burden_mean']*r['simulation_s'] for r in good)),walking_joint_burden_mean=float(np.mean([r['joint_burden_mean']for r in good])),walking_positive_work_sum_j=float(sum(r['positive_joint_work_j']for r in good)),female_successful_cases=sum(bool(r['face_alignment_feet'])for r in good),female_executed_cases=sum(bool(r.get('face_alignment_feet'))for r in rows),maximum_female_loaded_angle_deg=max(r['maximum_loaded_face_angle_deg']for r in good),maximum_female_landing_angle_deg=max(r['landing_face_alignment']['maximum_loaded_angle_deg']for r in good),maximum_off_face_fraction=max(r['off_face_load_fraction']for r in good),foot_counts=sorted(set(r['feet']for r in good)),scope='Successful tasks only for proxy means; all failures remain in overall score. Proxy is uncalibrated, not measured electrical energy.')
out['whole_sequence_by_modules']={str(n):float(np.mean([r['whole_sequence']['rotor_burden_hover_ratio'] for r in good if r['task']['modules']==n])) for n in range(3,9) if any(r['task']['modules']==n for r in good)}
out['high_speed_curves']={'successes':sum(r['task_success'] for r in rows if r['task']['speed']==.30 and r['task']['curvature']!=0), 'total':sum(r['task']['speed']==.30 and r['task']['curvature']!=0 for r in rows)}
(root/'additional_metrics.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
